//! 🧪️ Bounded original target selection agrees with portable prefix fixtures through denial and cancellation.
use super::*;
fn turn()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:4096}}
fn denied(mut g:RetainedCloneGrant,d:RetirementDemand,axis:usize)->Option<RetainedCloneGrant>{let v=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,3=>d.release_bytes,_=>d.depth};if v==0{return None}match axis{0=>g.maximum_items=0,1=>g.maximum_copy_bytes=v-1,2=>g.maximum_capacity_bytes=v-1,3=>g.maximum_release_bytes=v-1,_=>g.maximum_depth=v-1}Some(g)}
fn exact(p:RetainedCloneProgress,h:semio_framework_trace::HeapAllocationObservation){assert!(p.fits(turn()));assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}
fn close_value<T:semio_framework_value::retirement::RetireOwned>(value:T){let mut slot=Some(value);let mut close=RetainedCloneClose::default();for _ in 0..10000{if slot.is_none()&&close.is_empty(){return}let(step,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||if let Some(step)=close.begin_granted(&mut slot,turn()).unwrap(){step}else{close.step_granted(turn()).unwrap()});exact(step.progress(),h);}panic!("original target output retained custody")}
#[test]fn original_common_target_preserves_utf8_prefix_and_funded_partial_close(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){let paths:Vec<Option<Vec<String>>>=serde_json::from_value(case["paths"].clone()).unwrap();for cut in law["cancelCuts"].as_array().unwrap().iter().map(|cut|cut.as_u64().unwrap()as usize).chain(std::iter::once(usize::MAX)){let mut owner=OriginalCommonTarget::default();let mut turns=0;let mut complete=true;for path in &paths{if turns==cut{complete=false;break}let source=path.as_ref().map(|path|path as&dyn ArtifactOperationTargets);let d=owner.start_demands(source).unwrap();for axis in 0..5{if let Some(g)=denied(turn(),d,axis){let(p,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.start(source,g).unwrap());exact(p,h);assert_eq!(p,Default::default());}}let(p,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.start(source,turn()).unwrap());exact(p,h);turns+=1;for index in 0..10000{if turns==cut{complete=false;break}let d=owner.demands(source,4096).unwrap();for axis in 0..5{if let Some(g)=denied(turn(),d,axis){let(p,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(source,g).unwrap());exact(p,h);assert_eq!(p,Default::default());}}let(p,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(source,turn()).unwrap());exact(p,h);turns+=1;if owner.source_finished(){break}assert!(index<9999);}if !complete{break}}if cut==usize::MAX{assert!(complete);let((target,p),h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.take(turn()).unwrap().unwrap());exact(p,h);assert_eq!(target,serde_json::from_value::<Vec<String>>(case["expected"].clone()).unwrap());close_value(target);}owner.begin_close();for index in 0..10000{if owner.terminal_is_empty(){break}let(step,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(turn()).unwrap());exact(step.progress(),h);assert!(index<9999);}assert!(owner.terminal_is_empty());}}}
